#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE_1 2
#define GPIO_LINE_2 3
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean exit on Ctrl+C / SIGTERM */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the two GPIO lines */
    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    if (!line1) {
        perror("gpiod_chip_get_line(GPIO 2)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO 3)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output(GPIO 2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output(GPIO 3)");
        goto cleanup;
    }

    printf("GPIO 2 and GPIO 3 initialized as outputs. Press Ctrl+C to exit.\n");

    /* Main loop: toggle both lines every 0.1 seconds */
    while (keep_running) {
        int val = !gpiod_line_get_value(line1);
        if (gpiod_line_set_value(line1, val) < 0) {
            perror("gpiod_line_set_value(GPIO 2)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, val) < 0) {
            perror("gpiod_line_set_value(GPIO 3)");
            goto cleanup;
        }
        printf("GPIO 2: %d, GPIO 3: %d\n", val, val);
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "gpio-output-control", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    while (program_running) {
        int value = 1;
        if (gpiod_line_set_value(line, value) < 0) {
            fprintf(stderr, "Failed to set line value: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, value);
        fflush(stdout);

        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg16: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read failed: %s\n", strerror(errno));
        return -1;
    }
    *val = (buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous */
    uint16_t config = 0x8483;
    if (i2c_write_reg16(fd, CONFIG_REG, config) < 0) {
        goto cleanup;
    }

    while (running) {
        uint16_t raw;
        if (i2c_read_reg16(fd, CONVERSION_REG, &raw) < 0) {
            goto cleanup;
        }
        printf("ADS1115 AIN0: %d\n", raw);
        fflush(stdout);
        usleep(SAMPLE_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MLX90614_ADDR 0x5a
#define I2C_BUS "/dev/i2c-1"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02x failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02x failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_mlx90614(int fd, float *temperature) {
    uint16_t raw;
    if (i2c_read_reg16(fd, 0x06, &raw) < 0) {
        return -1;
    }
    *temperature = (float)raw * 0.02 - 273.15;
    return 0;
}

int main(void) {
    int fd = -1;
    float temperature;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02x: %s\n", MLX90614_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    while (g_running) {
        if (read_mlx90614(fd, &temperature) < 0) {
            fprintf(stderr, "Failed to read MLX90614 temperature.\n");
            break;
        }
        printf("Temperature: %.2f C\n", temperature);
        fflush(stdout);
        sleep(POLL_INTERVAL_SEC);
    }

    if (fd >= 0) {
        close(fd);
    }
    return 0;
}

