#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    /* Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous */
    uint16_t config = 0xC083; /* MSB: 1100 (AIN0 single-ended), LSB: 1000 0011 */
    uint8_t buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("write config");
        goto cleanup;
    }

    while (running) {
        uint8_t reg = CONVERSION_REG;
        if (write(fd, &reg, 1) != 1) {
            perror("write reg");
            goto cleanup;
        }

        uint8_t data[2];
        if (read(fd, data, 2) != 2) {
            perror("read data");
            goto cleanup;
        }

        int16_t raw = (data[0] << 8) | data[1];
        printf("Raw: %d\n", raw);
        fflush(stdout);

        usleep(100000); /* 100 ms */
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

