#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_1 2
#define GPIO_LINE_2 3
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_2, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "gpio-control", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LINE_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio-control", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LINE_2, strerror(errno));
        goto cleanup;
    }

    while (program_running) {
        int val1 = gpiod_line_get_value(line1);
        if (val1 < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", GPIO_LINE_1, strerror(errno));
            goto cleanup;
        }

        int val2 = gpiod_line_get_value(line2);
        if (val2 < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", GPIO_LINE_2, strerror(errno));
            goto cleanup;
        }

        if (val1 != val2) {
            fprintf(stderr, "Error: GPIO lines differ (%d, %d)\n", val1, val2);
            goto cleanup;
        }

        if (gpiod_line_set_value(line1, val1) < 0) {
            fprintf(stderr, "Failed to write line %d: %s\n", GPIO_LINE_1, strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, val2) < 0) {
            fprintf(stderr, "Failed to write line %d: %s\n", GPIO_LINE_2, strerror(errno));
            goto cleanup;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_LINE_1, val1, GPIO_LINE_2, val2);
        fflush(stdout);

        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

