#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Read temperature and humidity from the SI7021.
 * Returns 0 on success, -1 on I2C error, -2 on invalid reading.
 */
static int read_si7021(int fd, float *temperature, float *humidity) {
    uint8_t cmd[2] = {0x06, 0xE5}; /* Measure RH then T */
    uint8_t buf[6];

    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    /* SI7021 needs ~12 ms for a full measurement */
    usleep(15000);

    ssize_t n = read(fd, buf, 6);
    if (n != 6) {
        fprintf(stderr, "I2C read error: expected 6 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw_rh = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_t  = ((uint16_t)buf[3] << 8) | buf[4];

    /* Sanity-check ranges */
    if (raw_rh > 0x0FFF || raw_t > 0x3FFF) {
        fprintf(stderr, "Invalid SI7021 reading: raw_rh=0x%04X, raw_t=0x%04X\n",
                raw_rh, raw_t);
        return -2;
    }

    *humidity = ((float)raw_rh / 65536.0f) * 100.0f;
    *temperature = ((float)raw_t / 65536.0f) * 175.0f - 46.85f;

    return 0;
}

int main(void) {
    int fd = -1;
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("SI7021 reader started on %s (addr 0x%02X). Press Ctrl+C to exit.\n",
           I2C_BUS, SI7021_ADDR);

    while (g_running) {
        int rc = read_si7021(fd, &temperature, &humidity);
        if (rc == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else if (rc == -1) {
            fprintf(stderr, "I2C communication error; continuing.\n");
        } else {
            fprintf(stderr, "Invalid SI7021 reading; continuing.\n");
        }

        /* Sleep 5 s, but wake early on signal */
        for (int i = 0; i < 50 && g_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG     0x01

#define ADS1115_OS_BEGIN      0x8000
#define ADS1115_MUX_AIN0_GND  0x4000
#define ADS1115_PGA_4_096V    0x0200
#define ADS1115_MODE_SINGLE   0x0100
#define ADS1115_DR_128SPS     0x0080

static volatile sig_atomic_t g_stop = 0;
static int g_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write16: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read16: write reg failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read16: read failed: %s\n", strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_read(int fd, int16_t *value) {
    uint16_t config = ADS1115_OS_BEGIN | ADS1115_MUX_AIN0_GND |
                      ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE |
                      ADS1115_DR_128SPS;

    if (i2c_write16(fd, ADS1115_REG_CONFIG, config) < 0)
        return -1;

    /* Wait for conversion to complete (OS bit = 1) */
    for (int i = 0; i < 100; i++) {
        uint16_t cfg;
        if (i2c_read16(fd, ADS1115_REG_CONFIG, &cfg) < 0)
            return -1;
        if (cfg & ADS1115_OS_BEGIN)
            break;
        usleep(10000);
        if (i == 99) {
            fprintf(stderr, "ads1115_read: conversion timeout\n");
            return -1;
        }
    }

    uint16_t raw;
    if (i2c_read16(fd, ADS1115_REG_CONVERSION, &raw) < 0)
        return -1;

    *value = (int16_t)raw;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                ADS1115_ADDR, strerror(errno));
        close(g_fd);
        return 1;
    }

    for (int i = 0; i < 3 && !g_stop; i++) {
        int16_t val;
        if (ads1115_read(g_fd, &val) < 0) {
            fprintf(stderr, "ads1115_read failed\n");
            break;
        }
        printf("Reading %d: %d\n", i + 1, val);
        fflush(stdout);
        sleep(1);
    }

    if (g_fd >= 0)
        close(g_fd);
    return g_stop ? 1 : 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 6
#define CYCLE_COUNT 256

static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11, 23, 24};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++) lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio-control", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (int cycle = 0; cycle < CYCLE_COUNT && running; cycle++) {
        int state = (cycle & 0x80) ? 1 : 0;
        for (int i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], state) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for pin %u\n", pins[i]);
                goto cleanup;
            }
        }
        printf("Cycle %d: %s\n", cycle, state ? "HIGH" : "LOW");
        fflush(stdout);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    return ret;
}

