#define NUM_PINS 4
static const unsigned int pins[NUM_PINS] = {4, 17, 22, 27};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "gpio-output-control", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        values[i] = 1;
        if (gpiod_line_set_value(lines[i], values[i]) < 0) {
            fprintf(stderr, "gpiod_line_set_value failed for pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    printf("GPIO 4, 17, 22, 27 set to 1\n");
    fflush(stdout);

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                fprintf(stderr, "gpiod_line_get_value failed for pin %u\n", pins[i]);
                goto cleanup;
            }
            values[i] = v;
        }
        printf("GPIO 4: %d, 17: %d, 22: %d, 27: %d\n",
               values[0], values[1], values[2], values[3]);
        fflush(stdout);
        struct timespec ts = {1, 0};
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
