#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define CONSUMER "dht11_reader"

static volatile sig_atomic_t stop_flag = 0;

static void sig_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int wait_for_level(struct gpiod_line *line, int level, int timeout_ms) {
    int elapsed = 0;
    while (gpiod_line_get_value(line) != level) {
        if (stop_flag) return -1;
        usleep(1000);
        elapsed += 1;
        if (elapsed >= timeout_ms * 1000) return -1;
    }
    return elapsed;
}

static int read_dht11(struct gpiod_line *line, uint8_t *data) {
    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request line as output: %s\n", strerror(errno));
        return -1;
    }

    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(30);

    if (gpiod_line_request_input(line, CONSUMER) < 0) {
        fprintf(stderr, "Failed to request line as input: %s\n", strerror(errno));
        return -1;
    }

    if (wait_for_level(line, 0, 100) < 0) return -1;
    if (wait_for_level(line, 1, 100) < 0) return -1;
    if (wait_for_level(line, 0, 100) < 0) return -1;

    for (int i = 0; i < 40; i++) {
        if (wait_for_level(line, 1, 100) < 0) return -1;
        int high_us = 0;
        while (gpiod_line_get_value(line) == 1) {
            high_us++;
            if (high_us > 200) break;
            usleep(1);
        }
        data[i] = (high_us > 50) ? 1 : 0;
    }

    uint8_t checksum = data[0] + data[1] + data[2] + data[3];
    if (data[4] != checksum) {
        fprintf(stderr, "Checksum error: computed %d, received %d\n", checksum, data[4]);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT11_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    uint8_t data[5];
    int ret = read_dht11(line, data);

    if (stop_flag) {
        fprintf(stderr, "Interrupted by signal.\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ret < 0) {
        fprintf(stderr, "DHT11 read failed.\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("DHT11 data: %u %u %u %u %u\n", data[0], data[1], data[2], data[3], data[4]);

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

