    }

    if (gpiod_line_request_output(line2, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output(GPIO 3)");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        int val1 = (i % 2 == 0) ? 1 : 0;
        int val2 = (i % 2 == 0) ? 0 : 1;

        if (gpiod_line_set_value(line1, val1) < 0) {
            perror("gpiod_line_set_value(GPIO 2)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, val2) < 0) {
            perror("gpiod_line_set_value(GPIO 3)");
            goto cleanup;
        }

        printf("Cycle %d: GPIO 2 = %d, GPIO 3 = %d\n", i + 1, val1, val2);
        fflush(stdout);

        for (int s = 0; s < CYCLE_DELAY_SEC && running; s++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
