#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_2 2
#define GPIO_3 3
#define GPIO_18 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define PWM_DUTY_CYCLE 500
#define LOOP_DELAY_US 150000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed. Is the pigpio daemon running?\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_2, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_3, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_18, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(GPIO_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GPIO_3, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GPIO_18, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(GPIO_3, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(GPIO_18, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(GPIO_2, PWM_DUTY_CYCLE) != 0 ||
        gpioPWM(GPIO_3, PWM_DUTY_CYCLE) != 0 ||
        gpioPWM(GPIO_18, PWM_DUTY_CYCLE) != 0) {
        fprintf(stderr, "Error: failed to start PWM\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM started on GPIO 2, 3, 18 (duty %d/1000). Press Ctrl+C to stop.\n", PWM_DUTY_CYCLE);
    fflush(stdout);

    while (running) {
        int duty = gpioGetPWMdutycycle(GPIO_2);
        if (duty < 0) {
            fprintf(stderr, "Error: gpioGetPWMdutycycle failed on GPIO 2\n");
            break;
        }
        printf("GPIO 2: %d, GPIO 3: %d, GPIO 18: %d\n",
               duty, gpioGetPWMdutycycle(GPIO_3), gpioGetPWMdutycycle(GPIO_18));
        fflush(stdout);
        usleep(LOOP_DELAY_US);
    }

    gpioPWM(GPIO_2, 0);
    gpioPWM(GPIO_3, 0);
    gpioPWM(GPIO_18, 0);
    gpioTerminate();
    printf("\nPWM stopped, pigpio terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 18
#define CYCLES 3
#define CYCLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "gpio-cycle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < CYCLES && running; i++) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("Cycle %d: GPIO %d set to 1\n", i + 1, GPIO_LINE);
        fflush(stdout);

        usleep(CYCLE_DELAY_US);
        if (!running) break;

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("Cycle %d: GPIO %d set to 0\n", i + 1, GPIO_LINE);
        fflush(stdout);

        usleep(CYCLE_DELAY_US);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (running) {
        printf("Completed %d cycles.\n", CYCLES);
    } else {
        printf("\nInterrupted by signal.\n");
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 9
static const unsigned int pins[NUM_PINS] = {2, 3, 4, 5, 6, 7, 8, 9, 17};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = 0;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "gpio-output-control", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            values[i] = !values[i];
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "Failed to set GPIO line %u to %d\n", pins[i], values[i]);
                goto cleanup;
            }
        }
        printf("GPIO %u %u %u %u %u %u %u %u %u\n",
               pins[0], pins[1], pins[2], pins[3], pins[4],
               pins[5], pins[6], pins[7], pins[8]);
        fflush(stdout);
        usleep(50000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

