#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define OPT3001_ADDR 0x44
#define I2C_DEV "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", OPT3001_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /*
     * OPT3001 configuration (simplified):
     *  - Set power on (bit 0 of config register)
     *  - Set measurement mode (bit 1 of config register)
     *  - Set integration time (bits 4-7 of config register)
     *  - Set gain (bits 8-11 of config register)
     *  - Set ADC resolution (bits 12-15 of config register)
     *
     * For a basic reading, we can power on and start a measurement.
     */
    if (i2c_write_reg8(fd, 0x00, 0x01) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }
    usleep(10000); /* 10 ms power-on delay */

    uint16_t raw;
    if (i2c_read_reg16(fd, 0x00, &raw) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("OPT3001 Reading: %u\n", raw);

    close(fd);
    return EXIT_SUCCESS;
}

