#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>

#define BAUD_RATE B9600
#define PORT_NAME "/dev/ttyUSB0"
#define READ_TIMEOUT_MS 1000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int configure_serial(int fd) {
    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = (READ_TIMEOUT_MS / 100);

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = open(PORT_NAME, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", PORT_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (configure_serial(fd) != 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Serial port %s configured. Reading data...\n", PORT_NAME);

    char buffer[256];
    ssize_t bytes_read;
    int consecutive_errors = 0;

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = 0;
        timeout.tv_usec = (READ_TIMEOUT_MS * 1000);

        int ret = select(fd + 1, &readfds, NULL, NULL, &timeout);
        if (ret < 0) {
            if (errno == EINTR) continue;
            perror("select");
            break;
        }
        if (ret == 0) {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                fprintf(stderr, "Device not responding after %d ms\n", READ_TIMEOUT_MS);
                break;
            }
            continue;
        }

        bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            perror("read");
            break;
        }
        if (bytes_read == 0) {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                fprintf(stderr, "Device not responding after %d ms\n", READ_TIMEOUT_MS);
                break;
            }
            continue;
        }

        buffer[bytes_read] = '\0';
        printf("Received: %s\n", buffer);
        consecutive_errors = 0;
    }

    close(fd);
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

