        usleep(CYCLE_DELAY_US);
    }

    /* Release the line and close the chip on all exit paths */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (running) {
        printf("Completed %d cycles.\n", NUM_CYCLES);
    } else {
        printf("\nInterrupted by signal.\n");
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
