#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define CONSUMER "gpio-toggle"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean exit on Ctrl+C / SIGTERM */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d on %s: toggling every 1 ms. Press Ctrl+C to exit.\n",
           GPIO_LINE, GPIO_CHIP);
    fflush(stdout);

    int value = 0;
    while (keep_running) {
        value = !value;
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("GPIO %d set to %d\n", GPIO_LINE, value);
        fflush(stdout);
        usleep(1000); /* 1 ms */
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

