#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 17
#define CONSUMER "dht22_monitor"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    int data[5] = {0, 0, 0, 0, 0};
    int i, j;

    /* Start signal: pull low for >=1 ms, then high for 20-40 us */
    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request line as output\n");
        return -1;
    }
    gpiod_line_set_value(line, 0);
    usleep(2000);
    gpiod_line_set_value(line, 1);
    usleep(30);

    /* Switch to input with pull-up */
    if (gpiod_line_request_input(line, CONSUMER) < 0) {
        fprintf(stderr, "Failed to request line as input\n");
        return -1;
    }

    /* Wait for sensor response: low ~80 us, high ~80 us */
    int val;
    int timeout = 0;
    while ((val = gpiod_line_get_value(line)) == 1) {
        if (++timeout > 200) return -1;
        usleep(1);
    }
    timeout = 0;
    while ((val = gpiod_line_get_value(line)) == 0) {
        if (++timeout > 200) return -1;
        usleep(1);
    }
    timeout = 0;
    while ((val = gpiod_line_get_value(line)) == 1) {
        if (++timeout > 200) return -1;
        usleep(1);
    }

    /* Read 40 bits */
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            timeout = 0;
            while (gpiod_line_get_value(line) == 0) {
                if (++timeout > 200) return -1;
                usleep(1);
            }
            timeout = 0;
            while (gpiod_line_get_value(line) == 1) {
                if (++timeout > 200) return -1;
                usleep(1);
            }
            if (timeout > 50) {
                data[i] |= (1 << (7 - j));
            }
        }
    }

    /* Checksum */
    if (((data[0] + data[1] + data[2] + data[3]) & 0xFF) != data[4]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *hum = (float)((data[0] << 8) + data[1]) / 10.0;
    *temp = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    float temp, hum;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        if (read_dht22(line, &temp, &hum) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor\n");
        }
        sleep(2);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define REPORT_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int gpio, int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(gpio, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int gpios[] = {GPIO_17, GPIO_22, GPIO_27};
    for (size_t i = 0; i < sizeof(gpios) / sizeof(gpios[0]); i++) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on GPIO %d\n", gpios[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(gpios[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: gpioSetPWMrange failed on GPIO %d\n", gpios[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(gpios[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed on GPIO %d\n", gpios[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        int duty = (rand() % (PWM_RANGE + 1));
        int rc = 0;
        for (size_t i = 0; i < sizeof(gpios) / sizeof(gpios[0]); i++) {
            if (set_pwm(gpios[i], duty) != 0) {
                rc = 1;
            }
        }
        if (rc != 0) {
            break;
        }
        printf("GPIO %d, %d, %d: duty=%d\n", GPIO_17, GPIO_22, GPIO_27, duty);
        fflush(stdout);
        usleep(REPORT_INTERVAL_US);
    }

    for (size_t i = 0; i < sizeof(gpios) / sizeof(gpios[0]); i++) {
        gpioPWM(gpios[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

