#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define SSD1306_I2C_ADDR 0x3C
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void i2c_write_byte(uint8_t val) {
    if (write(i2c_fd, &val, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
    }
}

static void ssd1306_command(uint8_t cmd) {
    uint8_t buf[2] = {0x00, cmd};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "SSD1306 command write error: %s\n", strerror(errno));
    }
}

static void ssd1306_data(const uint8_t *data, int len) {
    uint8_t buf[1 + len];
    buf[0] = 0x40;
    memcpy(buf + 1, data, len);
    if (write(i2c_fd, buf, len + 1) != len + 1) {
        fprintf(stderr, "SSD1306 data write error: %s\n", strerror(errno));
    }
}

static void ssd1306_init(void) {
    ssd1306_command(0xAE); // Display off
    ssd1306_command(0xD5); // Set display clock divide ratio/oscillator frequency
    ssd1306_command(0x80);
    ssd1306_command(0xA8); // Set multiplex ratio
    ssd1306_command(0x3F);
    ssd1306_command(0xD3); // Set display offset
    ssd1306_command(0x00);
    ssd1306_command(0x40); // Set start line address
    ssd1306_command(0x8D); // Set memory addressing mode
    ssd1306_command(0x14);
    ssd1306_command(0x20); // Set segment re-map (column 127 mapped to SEG0)
    ssd1306_command(0xA1); // Set COM output scan direction (remapped mode)
    ssd1306_command(0xC8); // Set COM pins hardware configuration
    ssd1306_command(0xDA); // Set COM pins hardware configuration
    ssd1306_command(0x12);
    ssd1306_command(0x81); // Set contrast
    ssd1306_command(0xCF);
    ssd1306_command(0xD9); // Set pre-charge period
    ssd1306_command(0xF1);
    ssd1306_command(0xDB); // Set VCOMH deselect level
    ssd1306_command(0x40);
    ssd1306_command(0xA4); // Set display follow GDDRAM content
    ssd1306_command(0xA6); // Set normal display (not inverted)
    ssd1306_command(0xAF); // Display on
}

static void ssd1306_clear(void) {
    uint8_t zeros[SSD1306_WIDTH];
    memset(zeros, 0, sizeof(zeros));
    for (int page = 0; page < SSD1306_HEIGHT / 8; page++) {
        ssd1306_command(0xB0 + page);
        ssd1306_data(zeros, SSD1306_WIDTH);
    }
}

static void ssd1306_draw_text(int page, int col, const char *text) {
    ssd1306_command(0xB0 + page);
    ssd1306_command(0x00 + col);
    ssd1306_data((uint8_t *)text, strlen(text));
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SSD1306_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    ssd1306_init();
    ssd1306_clear();

    while (running) {
        ssd1306_clear();
        ssd1306_draw_text(0, 0, "Hello, World!");
        usleep(100000);
    }

    ssd1306_command(0xAE);
    close(i2c_fd);
    return 0;
}

