#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_8 8
#define GPIO_9 9
#define GPIO_11 11
#define GPIO_18 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_8, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_9, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_11, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_18, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioWrite(GPIO_8, 1) != 0 ||
            gpioWrite(GPIO_9, 0) != 0 ||
            gpioWrite(GPIO_11, 1) != 0 ||
            gpioWrite(GPIO_18, 0) != 0) {
            fprintf(stderr, "Error: failed to write GPIO states\n");
            break;
        }
        printf("GPIO 8=1, GPIO 9=0, GPIO 11=1, GPIO 18=0\n");
        fflush(stdout);
        sleep(1);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 23
#define ERROR_PIN 24

#define CHIP_NAME "gpiochip0"
#define CONSUMER "hcsr04"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(long long us) {
    struct timespec ts = {
        .tv_sec = us / 1000000LL,
        .tv_nsec = (us % 1000000LL) * 1000LL
    };
    nanosleep(&ts, NULL);
}

static void trigger_pulse(struct gpiod_line *trig) {
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("set trigger high");
        return;
    }
    sleep_us(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("set trigger low");
    }
}

static long measure_echo(struct gpiod_line *echo) {
    long long t0 = -1;
    long long t1 = -1;

    while (gpiod_line_get_value(echo) == 0) {
        if (!running) return -1;
        sleep_us(1);
    }
    t0 = now_us();

    while (gpiod_line_get_value(echo) == 1) {
        if (!running) return -1;
        sleep_us(1);
    }
    t1 = now_us();

    return (long)(t1 - t0);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *err = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa = {
        .sa_handler = sigint_handler,
        .sa_flags = 0
    };
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    err = gpiod_chip_get_line(chip, ERROR_PIN);
    if (!trig || !echo || !err) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("request trigger output");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("request echo input");
        goto cleanup;
    }
    if (gpiod_line_request_output(err, CONSUMER, 0) < 0) {
        perror("request error output");
        goto cleanup;
    }

    while (running) {
        trigger_pulse(trig);
        long echo_us = measure_echo(echo);

        if (echo_us < 0) {
            fprintf(stderr, "Error: HC-SR04 not responding (timeout or interrupted)\n");
            if (gpiod_line_set_value(err, 1) < 0) {
                perror("set error high");
            }
            sleep_us(200000);
            continue;
        }

        if (echo_us > 40000) {
            fprintf(stderr, "Error: HC-SR04 out of range (%ld us)\n", echo_us);
            if (gpiod_line_set_value(err, 1) < 0) {
                perror("set error high");
            }
            sleep_us(200000);
            continue;
        }

        printf("Distance: %.2f cm\n", echo_us / 58.0);
        fflush(stdout);
        sleep_us(200000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (err) gpiod_line_release(err);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOOP_DELAY_US 10000  /* 0.01 seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int rc;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return EXIT_FAILURE;
    }

    /* Set GPIO mode to output */
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main loop: set pixel colour and wait */
    while (running) {
        unsigned char red = 255;
        unsigned char green = 0;
        unsigned char blue = 0;

        /*
         * pigpio's gpioWrite takes a single byte value (0-255) for a
         * single-pin output.  To set RGB, we write the red byte, then
         * the green byte, then the blue byte.  This sequence is
         * representative of a single-channel RGB LED on GPIO 18.
         */
        if (gpioWrite(GPIO_PIN, red) != 0) {
            fprintf(stderr, "Failed to write red value to GPIO %d\n", GPIO_PIN);
            break;
        }
        if (gpioWrite(GPIO_PIN, green) != 0) {
            fprintf(stderr, "Failed to write green value to GPIO %d\n", GPIO_PIN);
            break;
        }
        if (gpioWrite(GPIO_PIN, blue) != 0) {
            fprintf(stderr, "Failed to write blue value to GPIO %d\n", GPIO_PIN);
            break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean up: set pin low and terminate pigpio */
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

