#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define HD44780_ADDR 0x28

#define HD44780_CMD 0x00
#define HD44780_DATA 0x40

#define HD44780_CLEARDISPLAY 0x01
#define HD44780_RETURNHOME 0x02
#define HD44780_ENTRYMODESET 0x04
#define HD44780_DISPLAYCONTROL 0x08
#define HD44780_FUNCTIONSET 0x20
#define HD44780_SETDDRAMADDR 0x80

#define HD44780_DISPLAYON 0x04
#define HD44780_CURSOROFF 0x02
#define HD44780_BLINKOFF 0x01

#define HD44780_ENTRYLEFT 0x02
#define HD44780_ENTRYSHIFTDECREMENT 0x00

#define HD44780_4BITMODE 0x00
#define HD44780_2LINE 0x08
#define HD44780_5x8DOTS 0x00

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(unsigned char val, unsigned char flags) {
    unsigned char buf[2] = { (val & 0xF0) | flags, (val << 4) | flags };
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_nibble(unsigned char nibble) {
    return i2c_write_byte(nibble, HD44780_CMD);
}

static int i2c_send_command(unsigned char cmd) {
    unsigned char high = (cmd & 0xF0);
    unsigned char low = ((cmd << 4) & 0xF0);
    if (i2c_write_nibble(high) < 0) return -1;
    if (i2c_write_nibble(low) < 0) return -1;
    usleep(5000);
    return 0;
}

static int i2c_send_data(unsigned char data) {
    unsigned char high = (data & 0xF0);
    unsigned char low = ((data << 4) & 0xF0);
    if (i2c_write_nibble(high | HD44780_DATA) < 0) return -1;
    if (i2c_write_nibble(low | HD44780_DATA) < 0) return -1;
    usleep(5000);
    return 0;
}

static int i2c_init_display(void) {
    if (i2c_write_nibble(0x30) < 0) return -1;
    usleep(50000);
    if (i2c_write_nibble(0x30) < 0) return -1;
    usleep(50000);
    if (i2c_write_nibble(0x30) < 0) return -1;
    usleep(50000);
    if (i2c_write_nibble(0x20) < 0) return -1;
    usleep(5000);

    if (i2c_send_command(HD44780_FUNCTIONSET | HD44780_4BITMODE | HD44780_2LINE | HD44780_5x8DOTS) < 0) return -1;
    if (i2c_send_command(HD44780_DISPLAYCONTROL | HD44780_DISPLAYON | HD44780_CURSOROFF | HD44780_BLINKOFF) < 0) return -1;
    if (i2c_send_command(HD44780_CLEARDISPLAY) < 0) return -1;
    if (i2c_send_command(HD44780_ENTRYMODESET | HD44780_ENTRYLEFT | HD44780_ENTRYSHIFTDECREMENT) < 0) return -1;
    if (i2c_send_command(HD44780_RETURNHOME) < 0) return -1;
    return 0;
}

static int i2c_set_cursor(int row, int col) {
    unsigned char addr = (row == 0) ? 0x00 : 0x40;
    addr += col;
    return i2c_send_command(HD44780_SETDDRAMADDR | addr);
}

static int i2c_write_string(const char *str) {
    while (*str) {
        if (i2c_send_data((unsigned char)*str) < 0) return -1;
        str++;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HD44780_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HD44780_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (i2c_init_display() < 0) {
        fprintf(stderr, "Failed to initialize display\n");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        char line1[17];
        char line2[17];
        snprintf(line1, sizeof(line1), "Reading 1: 123");
        snprintf(line2, sizeof(line2), "Reading 2: 456");

        if (i2c_set_cursor(0, 0) < 0) break;
        if (i2c_write_string(line1) < 0) break;

        if (i2c_set_cursor(1, 0) < 0) break;
        if (i2c_write_string(line2) < 0) break;

        sleep(10);
    }

    i2c_send_command(HD44780_CLEARDISPLAY);
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU6050\n");
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU6050 not detected at 0x%02X\n", MPU6050_ADDR);
        close(fd);
        return 1;
    }

    int16_t x, y, z;
    for (int i = 0; i < 100 && running; i++) {
        if (read_accel(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            close(fd);
            return 1;
        }
        printf("Accel: X=%d, Y=%d, Z=%d\n", x, y, z);
        usleep(10000);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_14 14
#define GPIO_LINE_15 15
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line14 = NULL;
    struct gpiod_line *line15 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line14 = gpiod_chip_get_line(chip, GPIO_LINE_14);
    if (!line14) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_14, strerror(errno));
        goto cleanup;
    }

    line15 = gpiod_chip_get_line(chip, GPIO_LINE_15);
    if (!line15) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_15, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line14, "gpio-output", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LINE_14, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line15, "gpio-output", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LINE_15, strerror(errno));
        goto cleanup;
    }

    while (running) {
        int val14 = gpiod_line_get_value(line14);
        if (val14 < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", GPIO_LINE_14, strerror(errno));
            goto cleanup;
        }

        int val15 = gpiod_line_get_value(line15);
        if (val15 < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", GPIO_LINE_15, strerror(errno));
            goto cleanup;
        }

        if (val14 != 0 || val15 != 0) {
            fprintf(stderr, "Invalid state: GPIO14=%d, GPIO15=%d\n", val14, val15);
            goto cleanup;
        }

        if (gpiod_line_set_value(line14, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n", GPIO_LINE_14, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line15, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n", GPIO_LINE_15, strerror(errno));
            goto cleanup;
        }

        printf("GPIO14=1, GPIO15=1\n");
        fflush(stdout);

        for (int i = 0; i < 5 && running; i++) {
            if (gpiod_line_set_value(line14, 0) < 0) {
                fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_LINE_14, strerror(errno));
                goto cleanup;
            }
            if (gpiod_line_set_value(line15, 0) < 0) {
                fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_LINE_15, strerror(errno));
                goto cleanup;
            }
            printf("GPIO14=0, GPIO15=0\n");
            fflush(stdout);
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line14) gpiod_line_release(line14);
    if (line15) gpiod_line_release(line15);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "raspberrypi_sensor"
#define MQTT_KEEP_ALIVE 60
#define MQTT_MQTT_VERSION_DEFAULT 3
#define MQTT_QOS 1
#define MQTT_TIMEOUT 1000
#define SENSOR_READ_INTERVAL_US 10000
#define MAX_RETRIES 5

static volatile sig_atomic_t running = 1;
static MQTTClient client;
static MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(void) {
    int value = gpioRead(18);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO 18: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

static int validate_reading(int reading) {
    return (reading >= 0 && reading <= 100);
}

static int publish_reading(int reading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = (void *)timestamp;
    pubmsg.payloadlen = strlen(timestamp);
    pubmsg.qos = MQTT_QOS;
    pubmsg.retained = 0;

    int result = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg);
    if (result != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", MQTTClient_strerror(result));
        return -1;
    }
    return 0;
}

int main(void) {
    int reading;
    int retries = 0;
    int exit_code = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(18, PI_INPUT);

    conn_opts.keepAliveInterval = MQTT_KEEP_ALIVE;
    conn_opts.cleansession = 1;
    conn_opts.connectTimeout = MQTT_TIMEOUT;

    int rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                               MQTT_MQTT_VERSION_DEFAULT, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error creating MQTT client: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return 1;
    }

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    while (running) {
        reading = read_sensor();
        if (reading < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting.\n");
                exit_code = 1;
                break;
            }
            gpioDelay(100000);
            continue;
        }

        if (!validate_reading(reading)) {
            fprintf(stderr, "Invalid sensor reading: %d\n", reading);
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting.\n");
                exit_code = 1;
                break;
            }
            gpioDelay(100000);
            continue;
        }

        if (publish_reading(reading) != 0) {
            fprintf(stderr, "Error publishing reading\n");
            exit_code = 1;
            break;
        }

        retries = 0;
        gpioDelay(SENSOR_READ_INTERVAL_US);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    if (exit_code == 0) {
        printf("Program terminated gracefully.\n");
    }
    return exit_code;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 23
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d toggled every %d seconds. Press Ctrl+C to exit.\n",
           GPIO_LINE, POLL_INTERVAL_SEC);

    while (running) {
        int current = gpiod_line_get_value(line);
        if (current < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        int new_value = current ? 0 : 1;
        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE, new_value);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nGPIO %d released. Exiting.\n", GPIO_LINE);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    22
#define ERROR_PIN   27

#define SPEED_OF_SOUND_CM_S 34300.0
#define MAX_DISTANCE_CM     400.0
#define TIMEOUT_US          30000
#define LOOP_DELAY_US       100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(long long us) {
    struct timespec ts;
    ts.tv_sec  = us / 1000000LL;
    ts.tv_nsec = (us % 1000000LL) * 1000LL;
    nanosleep(&ts, NULL);
}

static void set_pin(struct gpiod_line *line, int val) {
    if (gpiod_line_set_value(line, val) < 0) {
        perror("gpiod_line_set_value");
    }
}

static void pulse_trigger(struct gpiod_line *trigger) {
    set_pin(trigger, 1);
    sleep_us(10);
    set_pin(trigger, 0);
}

static float measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo) {
    long long start_time = 0, end_time = 0;
    long long elapsed;

    pulse_trigger(trigger);

    elapsed = now_us();
    while (gpiod_line_get_value(echo) == 0) {
        if (now_us() - elapsed > TIMEOUT_US) {
            return -1.0f;
        }
    }
    start_time = now_us();

    elapsed = start_time;
    while (gpiod_line_get_value(echo) == 1) {
        if (now_us() - elapsed > TIMEOUT_US) {
            return -1.0f;
        }
    }
    end_time = now_us();

    float pulse_duration = (float)(end_time - start_time) / 1000000.0f;
    float distance = (pulse_duration * SPEED_OF_SOUND_CM_S) / 2.0f;

    if (distance > MAX_DISTANCE_CM) {
        return -1.0f;
    }
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL, *error = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo   = gpiod_chip_get_line(chip, ECHO_PIN);
    error  = gpiod_chip_get_line(chip, ERROR_PIN);
    if (!trigger || !echo || !error) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        perror("gpiod_line_request_output trigger");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }
    if (gpiod_line_request_output(error, "hcsr04-error", 0) < 0) {
        perror("gpiod_line_request_output error");
        goto cleanup;
    }

    while (running) {
        float distance = measure_distance(trigger, echo);

        if (distance < 0.0f) {
            set_pin(error, 1);
            set_pin(trigger, 0);
            fprintf(stderr, "Error: Sensor timeout or out of range.\n");
        } else {
            set_pin(error, 0);
            set_pin(trigger, 0);
            printf("Distance: %.2f cm\n", distance);
        }

        sleep_us(LOOP_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo)    gpiod_line_release(echo);
    if (error)   gpiod_line_release(error);
    if (chip)    gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean exit on Ctrl+C / SIGTERM */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d initialized as output. Reporting state every 1 second.\n", GPIO_LINE);
    fflush(stdout);

    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("GPIO %d state: %d\n", GPIO_LINE, val);
        fflush(stdout);
        sleep(1);
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d released. Exiting.\n", GPIO_LINE);
    return EXIT_SUCCESS;
}

