#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "raspberrypi_sensor"
#define MQTT_KEEP_ALIVE 60
#define MQTT_QOS 1
#define MQTT_TIMEOUT 1000
#define SENSOR_READ_INTERVAL_MS 1000
#define SENSOR_READ_ATTEMPTS 3

static volatile sig_atomic_t running = 1;
static MQTTClient client;
static int pigpio_initialized = 0;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sensor_data(void) {
    int value = gpioRead(0);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

void cleanup(void) {
    if (pigpio_initialized) {
        gpioTerminate();
        pigpio_initialized = 0;
    }
    MQTTClient_free(&client);
}

int main(void) {
    int rc;
    int sensor_value;
    int attempt;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(0, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO 0 as input\n");
        cleanup();
        return 1;
    }

    if (MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTT_KEEP_ALIVE) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client\n");
        cleanup();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = MQTT_KEEP_ALIVE;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        cleanup();
        return 1;
    }

    while (running) {
        sensor_value = -1;
        for (attempt = 0; attempt < SENSOR_READ_ATTEMPTS; attempt++) {
            sensor_value = read_sensor_data();
            if (sensor_value >= 0) break;
            if (attempt < SENSOR_READ_ATTEMPTS - 1) {
                fprintf(stderr, "Retrying sensor read (%d/%d)...\n", attempt + 1, SENSOR_READ_ATTEMPTS);
                gpioDelay(100000);
            }
        }

        if (sensor_value < 0) {
            fprintf(stderr, "Sensor read failed after %d attempts. Exiting.\n", SENSOR_READ_ATTEMPTS);
            break;
        }

        char payload[32];
        snprintf(payload, sizeof(payload), "%d", sensor_value);

        rc = MQTTClient_publishMessage(client, MQTT_TOPIC, (unsigned int)strlen(payload), payload, MQTT_QOS);
        if (rc != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        }

        gpioDelay(SENSOR_READ_INTERVAL_MS * 1000);
    }

    MQTTClient_disconnect(client, 1000);
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000
#define REPORT_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int rc;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return EXIT_FAILURE;
    }

    /* Configure PWM pin */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main loop: report current state every REPORT_INTERVAL_SEC */
    while (running) {
        int duty = gpioGetPWMdutycycle(PWM_PIN);
        if (duty < 0) {
            fprintf(stderr, "Failed to read PWM duty cycle on GPIO %d\n", PWM_PIN);
            break;
        }

        printf("PWM duty cycle: %d\n", duty);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < REPORT_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    /* Clean shutdown: stop PWM and release pigpio */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define CHIP_NAME "gpiochip0"
#define TIMEOUT_US 200000
#define LOOP_DELAY_US 200000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int wait_for_level(struct gpiod_line *line, int level, long long timeout_us) {
    long long start = now_us();
    while (gpiod_line_get_value(line) != level) {
        if (!running) return -1;
        if (now_us() - start > timeout_us) return 0;
    }
    return 1;
}

static float measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trigger, 0) < 0) return -1.0f;
    usleep(2);
    if (gpiod_line_set_value(trigger, 1) < 0) return -1.0f;
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0) return -1.0f;

    long long start = 0, end = 0;
    int got_start = 0, got_end = 0;

    if (wait_for_level(echo, 1, TIMEOUT_US) == 0) return -1.0f;
    start = now_us();
    got_start = 1;

    if (wait_for_level(echo, 0, TIMEOUT_US) == 0) return -1.0f;
    end = now_us();
    got_end = 1;

    if (!got_start || !got_end) return -1.0f;

    float elapsed = (float)(end - start) / 1000000.0f;
    float distance = elapsed * 34300.0f / 2.0f;

    if (distance < 2.0f || distance > 400.0f) return -1.0f;
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        perror("gpiod_chip_get_line trigger");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line echo");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        perror("gpiod_line_request_output trigger");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }

    while (running) {
        float distance = measure_distance(trigger, echo);
        if (distance < 0.0f) {
            fprintf(stderr, "Error: HC-SR04 not responding or out of range.\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
        }
        fflush(stdout);
        usleep(LOOP_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_23 23
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define REPORT_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int gpios[] = {GPIO_17, GPIO_18, GPIO_22, GPIO_23};
    int num_gpios = (int)(sizeof(gpios) / sizeof(gpios[0]));

    for (int i = 0; i < num_gpios; i++) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", gpios[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(gpios[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", gpios[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(gpios[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", gpios[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < num_gpios; i++) {
            int duty = (rand() % (PWM_RANGE + 1));
            if (gpioPWM(gpios[i], duty) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", gpios[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM states: GPIO17=%d, GPIO18=%d, GPIO22=%d, GPIO23=%d\n",
               rand() % (PWM_RANGE + 1),
               rand() % (PWM_RANGE + 1),
               rand() % (PWM_RANGE + 1),
               rand() % (PWM_RANGE + 1));
        fflush(stdout);
        usleep(REPORT_INTERVAL_US);
    }

    for (int i = 0; i < num_gpios; i++) {
        gpioPWM(gpios[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "raspberrypi_sensor"
#define MQTT_KEEP_ALIVE 60
#define MQTT_MQTT_VERSION_DEFAULT 3
#define MQTT_QOS 1
#define MQTT_TIMEOUT_MS 1000
#define SENSOR_READ_INTERVAL_MS 1000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static MQTTClient client;
static MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int *value) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int v = gpioRead(18);
        if (v == 0 || v == 1) {
            *value = v;
            return 0;
        }
        fprintf(stderr, "Sensor read error (attempt %d/%d): %s\n",
                retries + 1, MAX_RETRIES, strerror(errno));
        retries++;
        gpioDelay(100000);
    }
    return -1;
}

static int validate_sensor_data(int value) {
    return (value >= 0 && value <= 1);
}

static int publish_sensor_data(int value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = (void *)timestamp;
    pubmsg.payloadlen = (int)strlen(timestamp);
    pubmsg.qos = MQTT_QOS;
    pubmsg.retained = 0;

    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT publish failed: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (client.context != NULL) {
        MQTTClient_disconnect(client, MQTT_TIMEOUT_MS);
        MQTTClient_destroy(&client);
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(18, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO 18 as input\n");
        gpioTerminate();
        return 1;
    }

    conn_opts.keepAliveInterval = MQTT_KEEP_ALIVE;
    conn_opts.cleansession = 1;
    conn_opts.connectTimeout = MQTT_TIMEOUT_MS;

    int rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS,
                               MQTT_CLIENT_ID,
                               MQTT_MQTT_VERSION_DEFAULT,
                               NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTTClient_create failed: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return 1;
    }

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTTClient_connect failed: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    printf("Connected to MQTT broker. Publishing sensor data...\n");

    while (running) {
        int sensor_value = -1;
        if (read_sensor_data(&sensor_value) != 0) {
            fprintf(stderr, "Sensor read failed after %d retries. Exiting.\n", MAX_RETRIES);
            break;
        }

        if (!validate_sensor_data(sensor_value)) {
            fprintf(stderr, "Invalid sensor data: %d\n", sensor_value);
            gpioDelay(SENSOR_READ_INTERVAL_MS * 1000);
            continue;
        }

        if (publish_sensor_data(sensor_value) != 0) {
            fprintf(stderr, "Failed to publish sensor data.\n");
        }

        gpioDelay(SENSOR_READ_INTERVAL_MS * 1000);
    }

    cleanup();
    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define CONFIG_VALUE 0xC183
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ads1115_data"
#define NUM_READINGS 10

static volatile sig_atomic_t running = 1;
static MQTTClient client;
static MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_ads1115(int handle) {
    char config[3];
    char reg[1] = {CONFIG_REG};
    char conv[2];

    if (i2cWriteDevice(handle, reg, 1) != 0) return -1;
    config[0] = (CONFIG_VALUE >> 8) & 0xFF;
    config[1] = CONFIG_VALUE & 0xFF;
    if (i2cWriteDevice(handle, config, 2) != 0) return -1;

    reg[0] = CONVERSION_REG;
    if (i2cWriteDevice(handle, reg, 1) != 0) return -1;
    if (i2cReadDevice(handle, conv, 2) != 2) return -1;

    int16_t raw = (conv[0] << 8) | conv[1];
    return (int)raw;
}

void publish_data(int handle, int value) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%d", value);
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;
    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
    }
}

void cleanup(int handle) {
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    MQTTClient_free(&client);
    i2cClose(handle);
    gpioTerminate();
}

int main() {
    int handle;
    int rc;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        gpioTerminate();
        return 1;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_create(&client, MQTT_BROKER, MQTT_PORT, NULL, MQTTCLIENT_PERSISTENCE_NONE);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < NUM_READINGS && running; i++) {
        int value = read_ads1115(handle);
        if (value < 0) {
            fprintf(stderr, "Failed to read from ADS1115\n");
            break;
        }
        publish_data(handle, value);
        sleep(1);
    }

    cleanup(handle);
    return 0;
}

#include <stdio.h>
