    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line17) {
        perror("gpiod_chip_get_line 17");
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line18) {
        perror("gpiod_chip_get_line 18");
        goto cleanup;
    }

    if (gpiod_line_request_output(line17, "gpio-toggle", 0) < 0) {
        perror("gpiod_line_request_output 17");
