#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB_00 0x88

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

struct bmp280_calib {
    uint16_t dig_T1; int16_t dig_T2, dig_T3;
    uint16_t dig_P1; int16_t dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
};

static int read_calibration(int fd, struct bmp280_calib *cal) {
    uint8_t buf[24];
    if (i2c_read_reg(fd, BMP280_REG_CALIB_00, buf, 24) < 0) return -1;
    cal->dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    cal->dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    cal->dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    cal->dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    cal->dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t g_t_fine;

static int32_t compensate_temperature(int32_t adc_T, const struct bmp280_calib *cal, int32_t *t_fine) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)cal->dig_T1)) * ((adc_T >> 4) - ((int32_t)cal->dig_T1))) >> 12) * ((int32_t)cal->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P, const struct bmp280_calib *cal, int32_t t_fine) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int64_t)cal->dig_P5) << 17);
    var2 = var2 + (((int64_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)cal->dig_P3) >> 8) + ((var1 * (int64_t)cal->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)cal->dig_P1) >> 33;
    if (var1 == 0) return 0;
    p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    return (uint32_t)p;
}

static int read_bmp280(int fd, const struct bmp280_calib *cal, float *temp, float *press) {
    uint8_t data[6];
    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) return -1;
    int32_t adc_P = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t adc_T = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t t_fine;
    int32_t T = compensate_temperature(adc_T, cal, &t_fine);
    *temp = T / 100.0f;
    *press = compensate_pressure(adc_P, cal, t_fine) / 256.0f;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error reading BMP280 ID: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (id != 0x58) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x58). Not a BMP280.\n", id);
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error resetting BMP280: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    usleep(2000);

    struct bmp280_calib cal;
    if (read_calibration(fd, &cal) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error writing ctrl_meas register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        float temp, press;
        if (read_bmp280(fd, &cal, &temp, &press) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temp, press);
        } else {
            fprintf(stderr, "Error reading BMP280 data: %s\n", strerror(errno));
            break;
        }
        sleep(5);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 4
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int duty_cycle = 500;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device absent or not responding).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM on GPIO %d started: duty cycle = %d (range 0-%d, freq %d Hz)\n",
           PWM_PIN, duty_cycle, PWM_RANGE, PWM_FREQUENCY);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    while (running) {
        gpioDelay(100000);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line5 = NULL, *line6 = NULL, *line13 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line5 = gpiod_chip_get_line(chip, GPIO_5);
    line6 = gpiod_chip_get_line(chip, GPIO_6);
    line13 = gpiod_chip_get_line(chip, GPIO_13);
    if (!line5 || !line6 || !line13) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line5, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output GPIO 5");
        goto cleanup;
    }
    if (gpiod_line_request_output(line6, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output GPIO 6");
        goto cleanup;
    }
    if (gpiod_line_request_output(line13, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output GPIO 13");
        goto cleanup;
    }

    if (gpiod_line_set_value(line5, 1) < 0) {
        perror("gpiod_line_set_value GPIO 5");
        goto cleanup;
    }
    if (gpiod_line_set_value(line6, 1) < 0) {
        perror("gpiod_line_set_value GPIO 6");
        goto cleanup;
    }
    if (gpiod_line_set_value(line13, 1) < 0) {
        perror("gpiod_line_set_value GPIO 13");
        goto cleanup;
    }

    printf("GPIO 5: 1, GPIO 6: 1, GPIO 13: 1\n");
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    if (line5) gpiod_line_release(line5);
    if (line6) gpiod_line_release(line6);
    if (line13) gpiod_line_release(line13);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "raspberrypi_sensor"
#define MQTT_KEEP_ALIVE 60
#define MQTT_QOS 1
#define MQTT_TIMEOUT 1000
#define SAMPLE_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;
static MQTTClient client;
static MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    int ret;
    int sensor_value;
    char message[256];
    time_t rawtime;
    struct tm *timeinfo;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    ret = MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (ret != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(ret));
        gpioTerminate();
        return 1;
    }

    conn_opts.keepAliveInterval = MQTT_KEEP_ALIVE;
    conn_opts.cleansession = 1;

    ret = MQTTClient_connect(client, &conn_opts);
    if (ret != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(ret));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    while (running) {
        sensor_value = gpioRead(4);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO 4: %s\n", strerror(errno));
            break;
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(message, sizeof(message), "%Y-%m-%d %H:%M:%S", timeinfo);
        snprintf(message + strlen(message), sizeof(message) - strlen(message), ", Sensor: %d", sensor_value);

        ret = MQTTClient_publishMessage(client, MQTT_TOPIC, (unsigned char *)message, strlen(message), MQTT_QOS, 0);
        if (ret != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(ret));
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_PINS 5
static const int pins[NUM_PINS] = {2, 3, 18, 23, 24};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device absent or not available).\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 128) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM set to 128 on GPIO %d, %d, %d, %d, %d\n",
           pins[0], pins[1], pins[2], pins[3], pins[4]);

    while (running) {
        gpioDelay(100000);
    }

    for (int i = 0; i < NUM_PINS; i++) {
        gpioPWM(pins[i], 0);
    }

    gpioTerminate();
    printf("PWM cleared, pigpio terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_17, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_22, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_27, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(GPIO_17, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GPIO_22, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GPIO_27, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_17, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(GPIO_22, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(GPIO_27, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty_cycle = 0;
    while (running) {
        if (gpioPWM(GPIO_17, duty_cycle) != 0 ||
            gpioPWM(GPIO_22, duty_cycle) != 0 ||
            gpioPWM(GPIO_27, duty_cycle) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle\n");
            break;
        }
        printf("GPIO 17, 22, 27: PWM duty cycle = %d\n", duty_cycle);
        fflush(stdout);

        duty_cycle = (duty_cycle + 1) % (PWM_RANGE + 1);
        usleep(LOOP_DELAY_US);
    }

    gpioPWM(GPIO_17, 0);
    gpioPWM(GPIO_22, 0);
    gpioPWM(GPIO_27, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT "JPEG"
#define CAPTURE_INTERVAL 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *buffer = NULL;
    size_t buffer_size = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: Device does not support video capture\n");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: Device does not support streaming I/O\n");
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        buffer = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            break;
        }

        FILE *fp = fopen("output.jpg", "wb");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file: %s\n", strerror(errno));
            break;
        }

        size_t bytes_written = fwrite(buffer, 1, buf.bytesused, fp);
        if (bytes_written != buf.bytesused) {
            fprintf(stderr, "Error writing to file\n");
            fclose(fp);
            break;
        }

        fclose(fp);

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            break;
        }

        sleep(CAPTURE_INTERVAL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        }
    }

    if (buffer != NULL && buffer != MAP_FAILED) {
        munmap(buffer, buffer_size);
    }

    if (fd >= 0) {
        close(fd);
    }

    return ret;
}

