#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define PWM_DUTY_CYCLE 500
#define REPORT_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm_state(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static int report_state(int gpio17, int gpio18, int gpio27) {
    printf("GPIO 17: %d, GPIO 18: %d, GPIO 27: %d\n", gpio17, gpio18, gpio27);
    fflush(stdout);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_17, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO 17\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_18, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO 18\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_27, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO 27\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(GPIO_17, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO 17\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GPIO_18, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO 18\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GPIO_27, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO 27\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_17, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO 17\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO_18, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO 18\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO_27, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO 27\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_pwm_state(GPIO_17, PWM_DUTY_CYCLE) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_pwm_state(GPIO_18, PWM_DUTY_CYCLE) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_pwm_state(GPIO_27, PWM_DUTY_CYCLE) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        report_state(PWM_DUTY_CYCLE, PWM_DUTY_CYCLE, PWM_DUTY_CYCLE);
        usleep(REPORT_INTERVAL_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define CONSUMER "dht22_reader"
#define MAX_TIMINGS 85
#define TIMEOUT_US 1000

static volatile sig_atomic_t stop_flag = 0;

static void sig_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    uint8_t laststate = 1;
    uint8_t counter = 0;
    uint8_t j = 0, i;

    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request line as output: %s\n", strerror(errno));
        return -1;
    }

    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(30);

    if (gpiod_line_request_input(line, CONSUMER) < 0) {
        fprintf(stderr, "Failed to request line as input: %s\n", strerror(errno));
        return -1;
    }

    for (i = 0; i < MAX_TIMINGS && !stop_flag; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == laststate && counter < TIMEOUT_US) {
            counter++;
            usleep(1);
        }
        laststate = gpiod_line_get_value(line);

        if (counter == TIMEOUT_US) {
            fprintf(stderr, "Timeout at byte %d\n", i);
            return -1;
        }

        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 2] <<= 1;
            if (counter > 16) {
                data[j / 2] |= 1;
            }
            j++;
        }
    }

    if (j < 40) {
        fprintf(stderr, "DHT22: Data incomplete (%d bytes)\n", j);
        return -1;
    }

    uint8_t checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) {
        fprintf(stderr, "DHT22: Checksum error (calc=%d, recv=%d)\n", checksum, data[4]);
        return -1;
    }

    uint16_t raw_h = (data[0] << 8) | data[1];
    uint16_t raw_t = (data[2] << 8) | data[3];

    *hum = (float)raw_h / 10.0f;
    if (raw_t & 0x8000) {
        *temp = -((float)(raw_t & 0x7FFF)) / 10.0f;
    } else {
        *temp = (float)raw_t / 10.0f;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temp, hum;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT22_PIN, strerror(errno));
        goto cleanup;
    }

    if (read_dht22(line, &temp, &hum) == 0) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        ret = EXIT_SUCCESS;
    } else {
        fprintf(stderr, "DHT22 read failed\n");
    }

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
