        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "rpi_mcp3008"
#define SAMPLE_INTERVAL_MS 1000
#define MCP3008_CHANNEL 0

static volatile sig_atomic_t running = 1;
static MQTTClient client;
static MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    int handle = gpioSerialReadOpen("/dev/pigpiod_if_0", 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open pigpio serial interface\n");
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = gpioSerialRead(handle, (char *)tx, 3);
    if (ret != 3) {
        fprintf(stderr, "Failed to write to pigpio serial interface\n");
        gpioSerialReadClose(handle);
        return -1;
    }

    ret = gpioSerialRead(handle, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Failed to read from pigpio serial interface\n");
        gpioSerialReadClose(handle);
        return -1;
    }

    gpioSerialReadClose(handle);

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

void publish_data(int sensor_value) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%d", sensor_value);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    int rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return 1;
    }

    printf("Connected to MQTT broker. Publishing sensor data...\n");

    while (running) {
        int sensor_value = read_mcp3008(MCP3008_CHANNEL);
        if (sensor_value >= 0) {
            publish_data(sensor_value);
        } else {
            fprintf(stderr, "Failed to read sensor value\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

static int xioctl(int fd, int request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void)
{
    const char *dev_name = "/dev/video0";
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    char *buffer = NULL;
    struct v4l2_buffer buf;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    fd = open(dev_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", dev_name, strerror(errno));
        return EXIT_FAILURE;
    }

    CLEAR(cap);
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", dev_name);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", dev_name);
        goto cleanup;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        goto cleanup;
    }

    CLEAR(req);
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        goto cleanup;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    fp = fopen("output.jpg", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening output file: %s\n", strerror(errno));
        goto cleanup;
    }

    size_t bytes_written = fwrite(buffer, 1, buf.bytesused, fp);
    if (bytes_written != buf.bytesused) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (buffer != NULL && buffer != MAP_FAILED) {
        munmap(buffer, buf.length);
    }
    if (fd >= 0) {
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        }
        close(fd);
    }
    return ret;
}

