    if (gpiod_line_request_output(line17, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output 17");
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output 18");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("gpiod_line_set_value 17");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, 1) < 0) {
            perror("gpiod_line_set_value 18");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 17 = 1, GPIO 18 = 1\n", i + 1);
        fflush(stdout);
        sleep(1);

        if (!running) break;

        if (gpiod_line_set_value(line17, 0) < 0) {
            perror("gpiod_line_set_value 17");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, 0) < 0) {
            perror("gpiod_line_set_value 18");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 17 = 0, GPIO 18 = 0\n", i + 1);
        fflush(stdout);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

