#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define CHIP_NAME "gpiochip0"
#define MAX_DISTANCE 400.0
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(2);

    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(10);

    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to reset trigger: %s\n", strerror(errno));
        return -1.0f;
    }

    long long start = now_us();
    while (gpiod_line_get_value(echo) == 0) {
        if (now_us() - start > TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1.0f;
        }
    }

    long long pulse_start = now_us();
    while (gpiod_line_get_value(echo) == 1) {
        if (now_us() - pulse_start > TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0f;
        }
    }
    long long pulse_end = now_us();

    long long elapsed = pulse_end - pulse_start;
    float distance = (elapsed / 1000000.0f) * 34300.0f / 2.0f;

    if (distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: distance %.2f exceeds max %.1f\n", distance, MAX_DISTANCE);
        return -1.0f;
    }
    return distance;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: cannot open %s: %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        fprintf(stderr, "Error: cannot get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: cannot get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Error: cannot request trigger as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Error: cannot request echo as input: %s\n", strerror(errno));
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance(trig, echo);
        if (distance < 0.0f) {
            fprintf(stderr, "Error: measurement failed\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
        }
        sleep(1);
    }

    printf("\nExiting...\n");
    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    return 0;
}

