#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define PCF8574_ADDR 0x20

static volatile sig_atomic_t running = 1;
static int fd = -1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t value) {
    if (write(fd, &value, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int pcf8574_write_all(int fd, const uint8_t *values) {
    for (int i = 0; i < 8; i++) {
        if (i2c_write_byte(fd, values[i]) < 0) {
            return -1;
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open i2c device");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t values[8] = {0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80};

    if (pcf8574_write_all(fd, values) < 0) {
        fprintf(stderr, "Failed to write to PCF8574\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("PCF8574 initialized and values written.\n");

    if (close(fd) < 0) {
        perror("close i2c device");
        return EXIT_FAILURE;
    }
    fd = -1;
    return EXIT_SUCCESS;
}

#include <stdio.h>
