#include <signal.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_27 27

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device absent or not responding).\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {GPIO_17, GPIO_18, GPIO_22, GPIO_27};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int states[] = {1, 0, 1, 0};

    for (int i = 0; i < num_pins; i++) {
        if (gpioWrite(pins[i], states[i]) != 0) {
            fprintf(stderr, "Error: failed to write GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("GPIO 17: %d, GPIO 18: %d, GPIO 22: %d, GPIO 27: %d\n",
           states[0], states[1], states[2], states[3]);

    gpioTerminate();
    return EXIT_SUCCESS;
}

