        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value 0 */
    ret = gpiod_line_request_output(line, "gpio-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d on %s initialized as output.\n", GPIO_LINE, GPIO_CHIP);

    while (running) {
        int value = !gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE, value);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_DEV "/dev/w1_slave"
#define GPIO_PIN 4
#define NUM_READINGS 3
#define READ_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temp_c) {
    FILE *fp = fopen(W1_DEV, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", W1_DEV, strerror(errno));
        return -1;
    }

    char line1[256];
    char line2[256];

    if (!fgets(line1, sizeof(line1), fp)) {
        fprintf(stderr, "Error reading line 1: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (!fgets(line2, sizeof(line2), fp)) {
        fprintf(stderr, "Error reading line 2: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "DS18B20 not found or CRC error\n");
        return -1;
    }

    char *temp_str = strstr(line2, "t=");
    if (!temp_str) {
        fprintf(stderr, "Temperature data not found\n");
        return -1;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    *temp_c = (float)temp_raw / 1000.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    for (int i = 0; i < NUM_READINGS && running; i++) {
        float temp_c;
        if (read_temperature(&temp_c) == 0) {
            printf("Temperature: %.2f C\n", temp_c);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
            return 1;
        }
        if (i < NUM_READINGS - 1 && running) {
            sleep(READ_INTERVAL);
        }
    }

    return 0;
}

