#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define ERROR_PIN   24

#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US   100000
#define ECHO_TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec  = us / 1000000,
        .tv_nsec = (long)(us % 1000000) * 1000
    };
    nanosleep(&ts, NULL);
}

static void set_pin(struct gpiod_line *line, int val) {
    if (gpiod_line_set_value(line, val) < 0) {
        perror("gpiod_line_set_value");
    }
}

static int read_pin(struct gpiod_line *line) {
    int v = gpiod_line_get_value(line);
    if (v < 0) {
        perror("gpiod_line_get_value");
        return -1;
    }
    return v;
}

static float measure_pulse(struct gpiod_line *echo_line) {
    struct timespec t_start, t_end;
    int val;

    if (clock_gettime(CLOCK_MONOTONIC, &t_start) < 0) {
        perror("clock_gettime");
        return -1.0f;
    }

    while (read_pin(echo_line) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &t_start) < 0) {
            perror("clock_gettime");
            return -1.0f;
        }
        if (t_start.tv_sec - t_start.tv_nsec > ECHO_TIMEOUT_US) {
            return -1.0f;
        }
    }

    if (clock_gettime(CLOCK_MONOTONIC, &t_start) < 0) {
        perror("clock_gettime");
        return -1.0f;
    }

    while (read_pin(echo_line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &t_end) < 0) {
            perror("clock_gettime");
            return -1.0f;
        }
        if (t_end.tv_sec - t_end.tv_nsec > ECHO_TIMEOUT_US) {
            return -1.0f;
        }
    }

    if (clock_gettime(CLOCK_MONOTONIC, &t_end) < 0) {
        perror("clock_gettime");
        return -1.0f;
    }

    long long diff_ns = (t_end.tv_sec - t_start.tv_sec) * 1000000000LL +
                        (t_end.tv_nsec - t_start.tv_nsec);
    return (float)diff_ns / 1000000000.0f;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig_line = NULL, *echo_line = NULL, *err_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    err_line  = gpiod_chip_get_line(chip, ERROR_PIN);
    if (!trig_line || !echo_line || !err_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig_line, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo_line, "hcsr04") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }
    if (gpiod_line_request_input(err_line, "hcsr04") < 0) {
        perror("gpiod_line_request_input (error)");
        goto cleanup;
    }

    while (running) {
        set_pin(trig_line, 1);
        sleep_us(TRIGGER_PULSE_US);
        set_pin(trig_line, 0);

        float pulse = measure_pulse(echo_line);
        if (pulse < 0.0f) {
            set_pin(err_line, 1);
            printf("ERROR\n");
        } else if (pulse < 2.0f || pulse > 400.0f) {
            set_pin(err_line, 1);
            printf("OUT OF RANGE\n");
        } else {
            set_pin(err_line, 0);
            printf("OK\n");
        }

        sleep_us(LOOP_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (err_line)  gpiod_line_release(err_line);
    if (chip)      gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
