#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define NUM_CYCLES 10

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean exit on Ctrl+C / SIGTERM */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio-cycle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Starting %d cycles on GPIO %d (BCM)...\n", NUM_CYCLES, GPIO_LINE);

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        int val = i % 2;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("Cycle %d: GPIO %d = %d\n", i + 1, GPIO_LINE, val);
        sleep(1);
    }

    /* Ensure the line is left in a known safe state */
    gpiod_line_set_value(line, 0);

    /* Release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

