#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_1 4
#define GPIO_2 17
#define GPIO_3 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio);
        return -1;
    }
    return value;
}

static int calculate_pwm(int v1, int v2, int v3) {
    int sum = v1 + v2 + v3;
    if (sum < 0) sum = 0;
    if (sum > PWM_RANGE) sum = PWM_RANGE;
    return sum;
}

static void set_pwm(int gpio, int pwm_value) {
    if (gpioPWM(gpio, pwm_value) != 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", gpio);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_1, PI_INPUT) != 0 ||
        gpioSetMode(GPIO_2, PI_INPUT) != 0 ||
        gpioSetMode(GPIO_3, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(GPIO_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GPIO_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GPIO_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_1, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(GPIO_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(GPIO_3, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int v1 = read_sensor(GPIO_1);
        int v2 = read_sensor(GPIO_2);
        int v3 = read_sensor(GPIO_3);

        if (v1 < 0 || v2 < 0 || v3 < 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int pwm_value = calculate_pwm(v1, v2, v3);

        set_pwm(GPIO_1, pwm_value);
        set_pwm(GPIO_2, pwm_value);
        set_pwm(GPIO_3, pwm_value);

        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d -> PWM: %d\n",
               GPIO_1, v1, GPIO_2, v2, GPIO_3, v3, pwm_value);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

