#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define NUM_CIRCLES 3
#define MAX_TIMINGS 85
#define TIMEOUT_US 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int last_state = 1;
    int bits = 0;

    for (int i = 0; i < NUM_CIRCLES; i++) {
        if (!running) return -1;

        if (gpiod_line_request_output(line, "dht22", 1) < 0) {
            fprintf(stderr, "request_output failed: %s\n", strerror(errno));
            return -1;
        }
        gpiod_line_set_value(line, 1);
        usleep(500000);
        gpiod_line_set_value(line, 0);
        usleep(20000);

        if (gpiod_line_request_input(line, "dht22") < 0) {
            fprintf(stderr, "request_input failed: %s\n", strerror(errno));
            return -1;
        }

        uint8_t last_index = 0;
        for (int j = 0; j < MAX_TIMINGS && bits < 40; j++) {
            int counter = 0;
            while (gpiod_line_get_value(line) == last_state) {
                counter++;
                if (counter == TIMEOUT_US) break;
                usleep(1);
            }
            last_state = gpiod_line_get_value(line);
            if (counter == TIMEOUT_US) break;

            if ((j >= 4) && (j % 2 == 0)) {
                data[last_index / 8] <<= 1;
                if (counter > 16)
                    data[last_index / 8] |= 1;
                last_index++;
            }
        }

        if (last_index < 40) {
            fprintf(stderr, "DHT22: insufficient data (%d bits)\n", last_index);
            return -1;
        }

        uint8_t checksum = data[0] + data[1] + data[2] + data[3];
        if (checksum != data[4]) {
            fprintf(stderr, "DHT22: checksum error (calc=%02x recv=%02x)\n", checksum, data[4]);
            return -1;
        }

        uint16_t raw_h = (data[0] << 8) | data[1];
        uint16_t raw_t = (data[2] << 8) | data[3];

        *hum = (float)raw_h / 10.0f;
        if (raw_t & 0x8000) {
            *temp = -((float)(raw_t & 0x7FFF)) / 10.0f;
        } else {
            *temp = (float)raw_t / 10.0f;
        }

        printf("Cycle %d: Temp=%.1fC, Hum=%.1f%%\n", i + 1, *temp, *hum);
        fflush(stdout);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT22_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    for (int i = 0; i < NUM_CIRCLES && running; i++) {
        float temp, hum;
        if (read_dht22(line, &temp, &hum) != 0) {
            fprintf(stderr, "DHT22 read failed on cycle %d\n", i + 1);
            break;
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

