#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_PINS 4
static const int pins[NUM_PINS] = {4, 17, 18, 27};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_PINS; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (int cycle = 0; cycle < 5 && running; cycle++) {
        printf("Cycle %d\n", cycle + 1);
        fflush(stdout);

        for (int i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pins[i], 255) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                cleanup();
                return EXIT_FAILURE;
            }
        }

        for (int i = 0; i < 60 && running; i++) {
            sleep(1);
        }

        for (int i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pins[i], 0) != 0) {
                fprintf(stderr, "Failed to set PWM to 0 on GPIO %d\n", pins[i]);
                cleanup();
                return EXIT_FAILURE;
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

