#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define NUM_READINGS 3
#define READ_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_sec(unsigned int sec) {
    while (sec-- > 0 && running) {
        sleep(1);
    }
}

/*
 * Read DHT22 via libgpiod.
 * Returns 0 on success, -1 on timeout or I/O error.
 * On success, fills humidity (%.1f) and temperature (%.1f).
 */
static int read_dht22(struct gpiod_line *line, float *humidity, float *temperature) {
    uint8_t data[5] = {0};
    int i;

    /* Start signal: pull low for >=1 ms, then high for 20-40 us */
    if (gpiod_line_request_output(line, "dht22", 0) < 0) {
        fprintf(stderr, "Failed to request line as output\n");
        return -1;
    }
    gpiod_line_set_value(line, 0);
    usleep(2000); /* 2 ms low */
    gpiod_line_set_value(line, 1);
    usleep(30);   /* 30 us high */

    /* Switch to input with pull-up */
    if (gpiod_line_request_input(line, "dht22") < 0) {
        fprintf(stderr, "Failed to request line as input\n");
        return -1;
    }

    /* Wait for sensor response: low ~80 us, high ~80 us */
    int val;
    int timeout = 1000; /* 1 ms timeout */
    while ((val = gpiod_line_get_value(line)) == 1 && timeout-- > 0) {
        usleep(1);
    }
    if (val != 0 || timeout <= 0) {
        fprintf(stderr, "DHT22: no response (stuck high)\n");
        return -1;
    }
    timeout = 1000;
    while ((val = gpiod_line_get_value(line)) == 0 && timeout-- > 0) {
        usleep(1);
    }
    if (val != 1 || timeout <= 0) {
        fprintf(stderr, "DHT22: no response (stuck low)\n");
        return -1;
    }
    timeout = 1000;
    while ((val = gpiod_line_get_value(line)) == 1 && timeout-- > 0) {
        usleep(1);
    }
    if (val != 0 || timeout <= 0) {
        fprintf(stderr, "DHT22: no response (response high)\n");
        return -1;
    }

    /* Read 40 bits */
    for (i = 0; i < 40; i++) {
        /* Wait for low-to-high transition (end of ~50 us low pulse) */
        timeout = 1000;
        while ((val = gpiod_line_get_value(line)) == 0 && timeout-- > 0) {
            usleep(1);
        }
        if (val != 1 || timeout <= 0) {
            fprintf(stderr, "DHT22: timeout waiting for bit %d low\n", i);
            return -1;
        }

        /* Measure high pulse width: ~26-28 us = '0', ~70 us = '1' */
        timeout = 1000;
        while ((val = gpiod_line_get_value(line)) == 1 && timeout-- > 0) {
            usleep(1);
        }
        if (val != 0 || timeout <= 0) {
            fprintf(stderr, "DHT22: timeout waiting for bit %d high\n", i);
            return -1;
        }

        int high_us = 0;
        timeout = 1000;
        while ((val = gpiod_line_get_value(line)) == 1 && timeout-- > 0) {
            high_us++;
            usleep(1);
        }
        if (high_us > 50) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    /* Checksum */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        fprintf(stderr, "DHT22: checksum error (calc=%u, recv=%u)\n", checksum, data[4]);
        return -1;
    }

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float humidity, temperature;
    int ret = 0;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    for (int i = 0; i < NUM_READINGS && running; i++) {
        printf("Reading %d/%d...\n", i + 1, NUM_READINGS);
        if (read_dht22(line, &humidity, &temperature) == 0) {
            printf("Humidity: %.1f %%\n", humidity);
            printf("Temperature: %.1f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read DHT22\n");
            ret = 1;
        }

        if (i < NUM_READINGS - 1 && running) {
            sleep_sec(READ_INTERVAL_SEC);
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (running) {
        printf("Program finished after %d readings.\n", NUM_READINGS);
    } else {
        printf("Interrupted by signal.\n");
    }

    return ret;
}

