        gpioSetMode(GPIO_18, PI_OUTPUT) != 0 ||
        gpioSetMode(GPIO_27, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioWrite(GPIO_17, 1) != 0 ||
            gpioWrite(GPIO_18, 0) != 0 ||
            gpioWrite(GPIO_27, 1) != 0) {
