#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define ERROR_PIN 18
#define OK_PIN 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_all(struct gpiod_line *t, struct gpiod_line *e,
                    struct gpiod_line *r, struct gpiod_line *o, int v) {
    if (gpiod_line_set_value(t, v) < 0) perror("set trigger");
    if (gpiod_line_set_value(e, v) < 0) perror("set echo");
    if (gpiod_line_set_value(r, v) < 0) perror("set error");
    if (gpiod_line_set_value(o, v) < 0) perror("set ok");
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    struct gpiod_line *error = gpiod_chip_get_line(chip, ERROR_PIN);
    struct gpiod_line *ok = gpiod_chip_get_line(chip, OK_PIN);
    if (!trigger || !echo || !error || !ok) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trigger, "hcsr04", 0) < 0 ||
        gpiod_line_request_input(echo, "hcsr04") < 0 ||
        gpiod_line_request_output(error, "hcsr04", 0) < 0 ||
        gpiod_line_request_output(ok, "hcsr04", 0) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 ready. Trigger once, then Ctrl+C.\n");

    set_all(trigger, echo, error, ok, 0);
    usleep(100000);

    if (gpiod_line_set_value(trigger, 1) < 0) {
        perror("trigger high");
        set_all(trigger, echo, error, ok, 0);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        perror("trigger low");
        set_all(trigger, echo, error, ok, 0);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int timeout = 0;
    while (gpiod_line_get_value(echo) == 0 && timeout < 30000) {
        usleep(10);
        timeout++;
    }
    if (timeout >= 30000) {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        set_all(trigger, echo, error, ok, 0);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    timeout = 0;
    while (gpiod_line_get_value(echo) == 1 && timeout < 30000) {
        usleep(10);
        timeout++;
    }
    if (timeout >= 30000) {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        set_all(trigger, echo, error, ok, 0);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    double elapsed = (end.tv_sec - start.tv_sec) +
                     (end.tv_nsec - start.tv_nsec) / 1e9;
    double distance = elapsed * 34300.0 / 2.0;

    if (distance > 400.0) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        set_all(trigger, echo, error, ok, 0);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Distance: %.2f cm\n", distance);
    set_all(trigger, echo, error, ok, 0);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

