        fprintf(stderr, "Failed to set line value: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d set to 1\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    if (interrupted) {
        fprintf(stderr, "\nInterrupted by signal, cleaning up...\n");
        goto cleanup;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

