#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define ERROR_PIN 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *err = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    err = gpiod_chip_get_line(chip, ERROR_PIN);
    if (!trig || !echo || !err) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }
    if (gpiod_line_request_output(err, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output (err)");
        goto cleanup;
    }

    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value (trig init)");
        goto cleanup;
    }
    usleep(50000);

    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value (trig high)");
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value (trig low)");
        goto cleanup;
    }

    struct timespec ts_start, ts_end;
    long long elapsed_ns = 0;
    int val;

    while (running) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value (echo)");
            goto cleanup;
        }
        if (val == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &ts_start) == -1) {
                perror("clock_gettime");
                goto cleanup;
            }
            while (running) {
                val = gpiod_line_get_value(echo);
                if (val < 0) {
                    perror("gpiod_line_get_value (echo)");
                    goto cleanup;
                }
                if (val == 0) break;
            }
            if (clock_gettime(CLOCK_MONOTONIC, &ts_end) == -1) {
                perror("clock_gettime");
                goto cleanup;
            }
            elapsed_ns = (ts_end.tv_sec - ts_start.tv_sec) * 1000000000LL +
                         (ts_end.tv_nsec - ts_start.tv_nsec);
            if (elapsed_ns > 20000000LL) {
                if (gpiod_line_set_value(err, 1) < 0) {
                    perror("gpiod_line_set_value (err)");
                    goto cleanup;
                }
                printf("ERROR: Echo pulse too long (%lld ns)\n", elapsed_ns);
            } else {
                if (gpiod_line_set_value(err, 0) < 0) {
                    perror("gpiod_line_set_value (err)");
                    goto cleanup;
                }
                printf("OK: Echo pulse %lld ns\n", elapsed_ns);
            }
        }
        usleep(1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (err) gpiod_line_release(err);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

