#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define ERROR_PIN 18

#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 100000
#define ECHO_TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long diff_us(const struct timespec *start, const struct timespec *end) {
    return (long long)(end->tv_sec - start->tv_sec) * 1000000LL +
           (end->tv_nsec - start->tv_nsec) / 1000LL;
}

static void set_error(struct gpiod_line *line, bool val) {
    if (gpiod_line_set_value(line, val ? 1 : 0) < 0) {
        perror("gpiod_line_set_value (error)");
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *err = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    err = gpiod_chip_get_line(chip, ERROR_PIN);
    if (!trig || !echo || !err) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }
    if (gpiod_line_request_output(err, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output (err)");
        goto cleanup;
    }

    while (running) {
        set_error(err, false);

        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value (trig high)");
            goto cleanup;
        }
        usleep(TRIGGER_PULSE_US);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value (trig low)");
            goto cleanup;
        }

        struct timespec t0, t1;
        clock_gettime(CLOCK_MONOTONIC, &t0);

        bool got_echo = false;
        int elapsed = 0;
        while (gpiod_line_get_value(echo) == 0 && elapsed < ECHO_TIMEOUT_US) {
            if (gpiod_line_get_value(echo) == 1) {
                got_echo = true;
                break;
            }
            usleep(1);
            elapsed++;
        }

        if (!got_echo) {
            set_error(err, true);
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &t1);

        bool got_echo_off = false;
        elapsed = 0;
        while (gpiod_line_get_value(echo) == 1 && elapsed < ECHO_TIMEOUT_US) {
            if (gpiod_line_get_value(echo) == 0) {
                got_echo_off = true;
                break;
            }
            usleep(1);
            elapsed++;
        }

        if (!got_echo_off) {
            set_error(err, true);
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &t1);

        long long dur = diff_us(&t0, &t1);
        if (dur < 0 || dur > 40000) {
            set_error(err, true);
            continue;
        }

        printf("Distance: %.2f cm\n", dur / 58.0);
        fflush(stdout);

        usleep(LOOP_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (err) gpiod_line_release(err);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
