    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATAL 0x14
#define TCS34725_CDATAH 0x15
#define TCS34725_RDATAL 0x16
#define TCS34725_RDATAH 0x17
#define TCS34725_GDATAL 0x18
#define TCS34725_GDATAH 0x19
#define TCS34725_BDATAL 0x1A
#define TCS34725_BDATAH 0x1B

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { (uint8_t)(TCS34725_COMMAND_BIT | reg), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, TCS34725_ID, &id) < 0) return -1;
    if (id != 0x44) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, TCS34725_ENABLE, 0x03) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_CONTROL, 0x00) < 0) return -1;
    return 0;
}

static int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t cl, cr, gl, gr, bl, br;
    if (i2c_read_reg8(fd, TCS34725_CDATAH, &cr) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_CDATAL, &cl) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_RDATAH, &cr) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_RDATAL, &cl) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_GDATAH, &cr) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_GDATAL, &cl) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_BDATAH, &cr) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_BDATAL, &cl) < 0) return -1;
    *clear = ((uint16_t)cr << 8) | cl;
    *red   = ((uint16_t)cr << 8) | cl;
    *green = ((uint16_t)cr << 8) | cl;
    *blue  = ((uint16_t)cr << 8) | cl;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(fd);
        return 1;
    }

    while (running) {
        uint16_t clear, red, green, blue;
        if (tcs34725_read_data(fd, &clear, &red, &green, &blue) < 0) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }
        printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);
        usleep(500000);
    }

    i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
    close(fd);
    return 0;
}

