#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_2 2
#define GPIO_3 3
#define GPIO_18 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define REPORT_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int gpio, int duty) {
    if (gpioPWM(gpio, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

static void report_state(int pwm2, int pwm3, int pwm18) {
    printf("PWM2=%d PWM3=%d PWM18=%d\n", pwm2, pwm3, pwm18);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or unavailable)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_18, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(GPIO_2, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", GPIO_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GPIO_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", GPIO_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GPIO_18, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", GPIO_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_2, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", GPIO_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO_3, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", GPIO_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO_18, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", GPIO_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pwm2 = 0, pwm3 = 0, pwm18 = 0;
    int duty = 0;

    while (running) {
        if (set_pwm(GPIO_2, duty) != 0) break;
        if (set_pwm(GPIO_3, duty) != 0) break;
        if (set_pwm(GPIO_18, duty) != 0) break;

        pwm2 = duty;
        pwm3 = duty;
        pwm18 = duty;
        report_state(pwm2, pwm3, pwm18);

        duty = (duty + 100) % (PWM_RANGE + 1);
        sleep(REPORT_INTERVAL);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

