#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>

#define BAUD_RATE B9600
#define PORT_NAME "/dev/ttyS0"
#define READ_TIMEOUT_MS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int configure_serial(int fd) {
    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr failed");
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = (READ_TIMEOUT_MS / 100);

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr failed");
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = open(PORT_NAME, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", PORT_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (configure_serial(fd) != 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction failed");
        close(fd);
        return EXIT_FAILURE;
    }

    unsigned char buffer[256];
    ssize_t bytes_read;

    while (running) {
        bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s", buffer);
            fflush(stdout);
        } else if (bytes_read < 0 && errno != EAGAIN && errno != EWOULDBLOCK) {
            perror("read failed");
            break;
        }
        usleep(100000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 3
#define GPIO_PIN_2 5

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean exit on Ctrl+C / SIGTERM */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the two GPIO lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line(GPIO 3)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO 5)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output(GPIO 3)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output(GPIO 5)");
        goto cleanup;
    }

    printf("Starting GPIO control loop. Press Ctrl+C to exit.\n");

    while (running) {
        /* Toggle both lines */
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(GPIO 3, 1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(GPIO 5, 1)");
            goto cleanup;
        }
        printf("GPIO 3 and GPIO 5 set to HIGH\n");

        sleep(1);

        if (!running) break;

        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(GPIO 3, 0)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(GPIO 5, 0)");
            goto cleanup;
        }
        printf("GPIO 3 and GPIO 5 set to LOW\n");

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    printf("GPIO lines released. Exiting.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define ERROR_PIN   24

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long measure_pulse(struct gpiod_line *echo) {
    struct timespec t_start, t_end;
    long long elapsed;

    while (gpiod_line_get_value(echo) == 0) {
        if (!running) return -1;
        usleep(10);
    }
    if (!running) return -1;
    clock_gettime(CLOCK_MONOTONIC, &t_start);

    while (gpiod_line_get_value(echo) == 1) {
        if (!running) return -1;
        usleep(10);
    }
    if (!running) return -1;
    clock_gettime(CLOCK_MONOTONIC, &t_end);

    elapsed = (t_end.tv_sec - t_start.tv_sec) * 1000000LL +
              (t_end.tv_nsec - t_start.tv_nsec) / 1000LL;
    return elapsed;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *err = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    err = gpiod_chip_get_line(chip, ERROR_PIN);
    if (!trig || !echo || !err) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }
    if (gpiod_line_request_input(err, "hcsr04") < 0) {
        perror("gpiod_line_request_input (error)");
        goto cleanup;
    }

    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value (trig init)");
        goto cleanup;
    }
    usleep(50000);

    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value (trig high)");
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value (trig low)");
        goto cleanup;
    }

    long long pulse = measure_pulse(echo);
    if (pulse < 0) {
        fprintf(stderr, "Error: HC-SR04 not responding or timeout.\n");
        if (gpiod_line_set_value(err, 1) < 0) {
            perror("gpiod_line_set_value (error high)");
        }
        goto cleanup;
    }

    if (gpiod_line_set_value(err, 0) < 0) {
        perror("gpiod_line_set_value (error low)");
        goto cleanup;
    }

    float distance = pulse / 58.0f;
    printf("Distance: %.2f cm\n", distance);

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (err)  gpiod_line_release(err);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

